document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".hamburger"),t=document.querySelector(".nav");e&&t&&(e.addEventListener("click",function(){const n=t.classList.toggle("open");e.setAttribute("aria-expanded",n?"true":"false")}),t.querySelectorAll("a").forEach(e=>e.addEventListener("click",()=>t.classList.remove("open"))))});